"""Place integration inputs into an OS source tree so incremental builds see them as fresh.

shutil.copy2 keeps the source file's old mtime, and a replaced input older than its existing
build output can be skipped as up to date. These helpers write atomically with a new mtime and
the source's permission bits, leave identical bytes untouched, and refuse to replace different
bytes or write through a symlink. Fresh mtimes do not prove the image contains the right bytes;
built-output byte verification is still required.
"""
import os
from pathlib import Path
import shutil
import tempfile

class Conflict(Exception):
    pass

def _install(target, data, mode):
    target = Path(target)
    if target.is_symlink():
        raise Conflict(f'Refusing to write through symlink: {target}')
    if target.exists():
        if target.read_bytes() == data:
            return False
        raise Conflict(f'Unexpected existing overlay target: {target}')
    target.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix='.'+target.name+'.', dir=target.parent)
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.chmod(temporary, mode)
        # Hard-link creation fails if the target appeared meanwhile, so nothing is overwritten.
        try:
            os.link(temporary, target)
        except FileExistsError:
            raise Conflict(f'Overlay target appeared during apply: {target}')
    finally:
        os.unlink(temporary)
    os.utime(target)
    return True

def install_copy(source, target):
    """Copy source to target; return True if written, False if identical bytes were already there."""
    source = Path(source)
    return _install(target, source.read_bytes(), source.stat().st_mode & 0o7777)

def install_bytes(target, data, mode=0o644):
    """Write generated bytes with the same fresh/no-op/conflict rules as install_copy."""
    return _install(target, data, mode)

def copy_fresh(source, target):
    """Replace a build output with source bytes and a new mtime (unlike shutil.copy2)."""
    shutil.copyfile(source, target)
    shutil.copymode(source, target)
    os.utime(target)
